int sum(int *a, int n) {
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] < 0) {
            continue;
        } else if (a[i] == 0) {
            break;
        }
        total += a[i];
    }
    return total;
}

int main(void) {
    int nums[] = {1,2,-3,4,0,5};
    int result = sum(nums, 6);
#if defined(TEST)
    if (result > 5) {
        puts(PLATFORM);
    } else {
        return 1;
    }
#else
    result = SQUARE(result);
#endif
    while (result > 7) {
        result--;
    }
    return result != 7;
}

