#include <stdio.h>

typedef enum {
    CIRCLE,
    SQUARE,
    TRIANGLE
} Kind;

typedef struct Shape Shape;
struct Shape {
    Kind kind;
    double size;
};

double area(Shape s) {
    double k = 0.0;
    switch (s.kind) {
        case CIRCLE:
            k = 3.14159;
            break;
        case SQUARE:
            k = 1;
            break;
        default:
            k = 0.433;
            break;
    }
    return k * s.size * s.size;
}

int main(void) {
    Shape shapes[3] = {{CIRCLE, 1}, {SQUARE, 2}, {TRIANGLE, 3}};
    for (int i = 0; i < 3; i++) {
        printf("shape %d area %g\n", i, area(shapes[i]));
    }
    return 0;
}

