typedef struct Pair Pair;
struct Pair {
    int a,b;
};

unsigned gcd(unsigned a, unsigned b) {
    return b ? gcd(b, a % b) : a;
}

int main(void) {
    Pair p = {84, 36};
    unsigned char small = 200;
    long long big = 1L << 40;
    printf("gcd %d %d = %u\n", p.a, p.b, gcd(p.a, p.b));
    printf("u8 %u i64 %ld\n", small, (long)big);
    return 0;
}

#include <stdlib.h>

typedef struct Node Node;
struct Node {
    int value;
    Node *next;
};

int main(void) {
    Node *head = malloc(sizeof *head);
    if (head == NULL) {
        return 1;
    }
    head->value = 7;
    head->next = NULL;
    int answer = head->value;
    free(head);
    return answer != 7;
}

#include <stdio.h>

int parse(const char *text) {
    int value = 0;
    int sign = 1;
    if (*text == '-') {
        sign = -1;
        text++;
    }
    while (*text >= '0' && *text <= '9') {
        value = value * 10 + *text++ - '0';
    }
    return sign * value;
}

int main(void) {
    return parse("-123tail") != -123 || parse("0") != 0 || parse("42") != 42;
}

void reverse(int *values, int size) {
    for (int left = 0; left < size/2; left++) {
        int other = size-left-1;
        int tmp = values[left];
        values[left] = values[other];
        values[other] = tmp;
    }
}

int main(void) {
    int values[] = {1,2,3,4,5};
    reverse(values, 5);
    return values[0] != 5 || values[4] != 1 || values[2] != 3;
}
